         count(*) as total
  from public.catalog_items
),
top as (
  select ci.title, s.name as fonte, ci.tags, round((1 - (ci.embedding <=> q.v))::numeric, 4) as sim
  from public.catalog_items ci, q, public.sources s
  where s.id = ci.source_id and ci.embedding is not null
    and not (ci.tags && array['quadro'])
  order by ci.embedding <=> q.v
  limit 40
)
select row_number() over (order by top.sim desc) as n, top.title, top.fonte, top.tags::text, top.sim,
       tot.com_tag_espelho, tot.com_tag_quadro, tot.sem_tag_tipo, tot.total
from top, tot
order by top.sim desc;
